// Bao the treasure dragon — Rive edition (hand-inked shoujo magical-girl dragon on his coin hoard).
// He is a Rive animation (bao.riv, embedded below) driven by its state machine "Bao".
// His view model takes: mood (0 sleepy, 1 happy, 2 proud, 3 excited), fill (0-100: how big
// his hoard is; six tiers of coins rise around him as it grows) and a chomp trigger
// (coins rain into the hoard). The art and motion live in the .riv; this file only feeds it.
//   baoHTML(mood, fill, opts) → HTML for a Bao canvas (used by dragonSVG in mascots.js)
//   baoChomp()               → coins rain in on every Bao on screen (or as soon as one loads)

const BAO_RIV = '';
const MOOD_NUM = { sleepy: 0, happy: 1, proud: 2, excited: 3 };
const RIGS = new Map(); // canvas → { r, vm, loaded, chomp }
let rivBytes = null;
let pendingChomp = false;
const rivBuffer = () => {
  if (!rivBytes) rivBytes = Uint8Array.from(atob(BAO_RIV), ch => ch.charCodeAt(0));
  return rivBytes.slice().buffer;
};
const canvases = () => [...document.querySelectorAll('canvas.bao-rive')];
const calm = () => document.documentElement.classList.contains('reduce-motion') || matchMedia('(prefers-reduced-motion: reduce)').matches;

function vmSet(rig, name, value) {
  try { const p = rig.vm?.number(name); if (p) p.value = value; } catch (e) { /* older runtime */ }
}
function vmFire(rig, name) {
  try { rig.vm?.trigger(name)?.trigger(); } catch (e) { /* older runtime */ }
}
function syncMotion(rig) {
  if (!rig.loaded) return;
  if (calm()) { if (rig.r.isPlaying) rig.r.pause(); }
  else if (!rig.r.isPlaying) rig.r.play();
}
function attach(cv) {
  if (RIGS.has(cv) || !window.rive) return;
  const rig = { r: null, vm: null, loaded: false };
  RIGS.set(cv, rig);
  rig.r = new rive.Rive({
    buffer: rivBuffer(),
    canvas: cv,
    stateMachines: 'Bao',
    autoplay: true,
    autoBind: true,
    layout: new rive.Layout({ fit: rive.Fit.Contain, alignment: rive.Alignment.Center }),
    onLoad: () => {
      rig.loaded = true;
      rig.vm = rig.r.viewModelInstance;
      rig.r.resizeDrawingSurfaceToCanvas();
      vmSet(rig, 'mood', MOOD_NUM[cv.dataset.mood] ?? 1);
      vmSet(rig, 'fill', Math.max(0, Math.min(100, +cv.dataset.fill || 0)));
      if (pendingChomp && !calm()) { pendingChomp = false; vmFire(rig, 'chomp'); }
      if (calm()) setTimeout(() => syncMotion(rig), 120);
    },
  });
}
function detach(cv) {
  const rig = RIGS.get(cv); if (!rig) return;
  RIGS.delete(cv);
  try { rig.r.cleanup(); } catch (e) { /* already gone */ }
}
function scan() {
  canvases().forEach(attach);
  for (const cv of RIGS.keys()) if (!cv.isConnected) detach(cv);
}

export function baoHTML(mood = 'happy', fill = 0, { label = 'Bao the treasure dragon' } = {}) {
  const f = Math.round(Math.max(0, Math.min(1, fill)) * 100);
  return `<canvas class="bao-rive" width="900" height="483" data-mood="${mood}" data-fill="${f}" role="img" aria-label="${label}"></canvas>`;
}

// coins rain into the hoard (when you save); waits for a Bao that is still loading
export function baoChomp() {
  const rigs = [...RIGS.entries()].filter(([cv, r]) => cv.isConnected && r.loaded).map(([, r]) => r);
  if (calm()) return;
  if (rigs.length) rigs.forEach(r => vmFire(r, 'chomp'));
  else pendingChomp = true;
}

// attach to Bao canvases as the app renders them, let go of the ones it removes
scan();
new MutationObserver(scan).observe(document.body, { childList: true, subtree: true });
addEventListener('resize', () => RIGS.forEach(rig => { if (rig.loaded) rig.r.resizeDrawingSurfaceToCanvas(); }));
setInterval(() => RIGS.forEach(syncMotion), 1000);
